  protected async toggleHold(person: Person): Promise<void> {
    this.clearRowError(person.id);
    const sheet = this.sheet();
    if (!sheet) return;
    try {
      const saved = await this.service.hold(sheet, person.id, !person.held);
      if (this.sheet() !== sheet) return;
      this.put(saved);
