  /** Whether the claim counts in the live totals: OPEN or SETTLED, but not OPEN while its person is
   *  on hold. */
  private countsLive(claim: Claim, person: Person): boolean {
    return counts(claim) && !(person.held && claim.status === 'OPEN');
