169	                    (click)="takeStatement(p)"
170	                  >
171	                    Statement
172	                  </button>
173	                  <label [for]="'person-retire-date-' + p.id">Retire from</label>
174	                  <input
175	                    [id]="'person-retire-date-' + p.id"
176	                    data-testid="person-retire-date"
177	                    [value]="retireDates()[p.id] ?? ''"
178	                    (input)="setRetireDate(p.id, value($event))"
179	                  />
180	                  <button
181	                    type="button"
182	                    data-testid="person-retire"
183	                    [attr.aria-label]="'Retire ' + p.name"
184	                    (click)="retire(p)"
185	                  >
186	                    Retire
187	                  </button>
188	                  <button
189	                    type="button"
190	                    data-testid="person-hold-toggle"
191	                    [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name"
192	                    (click)="toggleHold(p)"
193	                  >
194	                    {{ p.held ? 'Release' : 'Hold' }}
195	                  </button>
196	                  @if (rowErrors()[p.id]; as message) {
197	                    <p role="alert" class="error" data-testid="person-error">{{ message }}</p>
198	                  }
199	                </td>
200	              </tr>
201	            }
202	          </tbody>
203	        </table>
204	        <p>
205	          Claimed in total: <span data-testid="rollup-claimed-total">{{ claimedTotal() }}</span>
206	        </p>
207	        <p>
208	          Due in total: <span data-testid="rollup-due-total">{{ dueTotal() }}</span>
209	        </p>
210	        <p>
211	          Overdue: <span data-testid="rollup-overdue-count">{{ overdueTotal().count }}</span>,
212	          due on them <span data-testid="rollup-overdue-total">{{ money(overdueTotal().cents) }}</span>
213	        </p>
214	      }
215	    </section>
216	  `,
217	  styles: `
218	    form {
219	      display: flex;
220	      flex-wrap: wrap;
221	      gap: 0.5rem;
222	      align-items: center;
223	      margin-bottom: 1rem;
224	    }
225	    .error {
226	      color: #a40000;
227	      margin: 0;
228	    }
229	    table {
230	      border-collapse: collapse;
231	    }
232	    th,
233	    td {
234	      text-align: left;
235	      padding: 0.25rem 0.75rem 0.25rem 0;
236	      white-space: pre;
237	      vertical-align: top;
238	    }
239	    .visually-hidden {
240	      position: absolute;
241	      width: 1px;
242	      height: 1px;
243	      overflow: hidden;
244	      clip: rect(0 0 0 0);
245	    }
246	  `,
247	})
248	export class People {
249	  private readonly session = inject(Session);
250	  private readonly service = inject(PeopleService);
251	  private readonly claimsService = inject(ClaimsService);
252	  private readonly ratesService = inject(RatesService);
253	  private readonly settingsService = inject(SettingsService);
254	  private readonly statementsService = inject(StatementsService);
255	  private readonly periodsService = inject(PeriodsService);
256	
257	  protected readonly grades = GRADES;
258	  protected readonly money = money;
259	  protected readonly people = signal<Person[]>([]);
260	  /** Whether retired people are listed; off when the screen is first opened, kept across sheet loads. */
261	  protected readonly showRetired = signal(false);
262	  /** The people listed: everyone, or only those not retired unless "show retired" is on. */
263	  protected readonly shownPeople = computed(() =>
264	    this.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
265	  );
266	  /** The retire-from date typed on each person's row, by person id. */
267	  protected readonly retireDates = signal<Record<number, string>>({});
268	  /** The sheet's claims, newest first. */
269	  protected readonly claims = signal<Claim[]>([]);
270	  private readonly claimsByPerson = computed(() => {
271	    const by = new Map<number, Claim[]>();
272	    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
273	    return by;
274	  });
275	  protected readonly claimedTotal = computed(() =>
276	    money(this.people().reduce((sum, p) => sum + this.claimedCentsOf(p), 0)),
277	  );
278	  /** The sheet's statements, in the order they were taken. */
279	  protected readonly statements = signal<Statement[]>([]);
280	  private readonly statementsByPerson = computed(() => {
281	    const by = new Map<number, Statement[]>();
282	    for (const s of this.statements()) by.set(s.personId, [...(by.get(s.personId) ?? []), s]);
283	    return by;
284	  });
285	  /** The error of the last refused action on each person's row, by person id. */
286	  protected readonly rowErrors = signal<Record<number, string>>({});
287	  /** The sheet's rates, by grade. */
288	  protected readonly rates = signal<Rate[]>([]);
289	  /** The sheet's floor, in cents: the least a claim's live due can be. */
290	  protected readonly floor = signal(FLOOR_CENTS);
291	  /** The sheet's terms, in days: how long after its date a claim is due by. */
292	  protected readonly terms = signal(TERMS_DAYS);
293	  /** The sheet's late percent, with two decimals. */
294	  protected readonly latePct = signal(LATE_PCT);
295	  /** What the claims' late charges are worked from. */
296	  private readonly lateness = computed<Lateness>(() => ({
297	    terms: this.terms(),
298	    today: this.session.today(),
299	    latePct: this.latePct(),
300	  }));
301	  /** The sheet's periods. */
302	  protected readonly periods = signal<Period[]>([]);
303	  /** Each period's due-total, by name: what is due on the OPEN and SETTLED claims dated in it, as
304	   *  each claim shows it (a claim with nothing due is skipped). */
305	  protected readonly periodDueTotals = computed(() => {
306	    const sums: Record<string, number> = {};
307	    for (const p of this.periods()) sums[p.name] = 0;
308	    for (const person of this.people()) {
309	      for (const c of this.claimsOf(person.id)) {
310	        if (!this.countsLive(c, person)) continue;
311	        const period = periodOn(this.periods(), c.date);
312	        if (period === null) continue;
313	        sums[period.name] += claimShownCents(c, this.rates(), person.grade, this.floor(), this.lateness()) ?? 0;
314	      }
315	    }
316	    return Object.fromEntries(Object.entries(sums).map(([name, sum]) => [name, money(sum)]));
317	  });
318	  protected readonly dueTotal = computed(() => {
319	    let sum = 0;
320	    for (const p of this.people()) sum += this.dueCentsOf(p) ?? 0;
321	    return money(sum);
322	  });
323	  /** How many of everyone's counting claims are overdue, and what is due on them, in cents. */
324	  protected readonly overdueTotal = computed(() =>
325	    this.people().reduce(
326	      (sum, p) => {
327	        const o = this.overdueOf(p);
328	        return { count: sum.count + o.count, cents: sum.cents + o.cents };
329	      },
330	      { count: 0, cents: 0 },
331	    ),
332	  );
333	  protected readonly name = signal('');
334	  protected readonly grade = signal<Grade>('A');
335	  protected readonly editingId = signal<number | null>(null);
336	  /** The version of the person the editor loaded. */
337	  private editingVersion = 0;
338	  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
339	  private submitting = false;
340	  protected readonly error = signal<string | null>(null);
341	  protected readonly quickName = signal('');
342	  protected readonly quickAmount = signal('');
343	  protected readonly quickError = signal<string | null>(null);
344	  /** A quick-add is waiting for its answer; another meanwhile is ignored. */
345	  private quickAdding = false;
346	  private readonly sheet = computed(() => this.session.sheetId());
347	
348	  constructor() {
349	    // Re-read the sheet's people from the store every time a sheet is loaded.
350	    effect(() => {
351	      const sheet = this.sheet();
352	      this.session.loads();
353	      this.people.set([]);
354	      this.claims.set([]);
355	      this.rates.set([]);
356	      this.floor.set(FLOOR_CENTS);
357	      this.terms.set(TERMS_DAYS);
358	      this.latePct.set(LATE_PCT);
359	      this.statements.set([]);
360	      this.periods.set([]);
361	      this.rowErrors.set({});
362	      this.retireDates.set({});
363	      this.reset();
364	      this.quickName.set('');
365	      this.quickAmount.set('');
366	      this.quickError.set(null);
367	      if (sheet) void this.read(sheet);
368	    });
369	  }
370	
371	  protected value(event: Event): string {
372	    return (event.target as HTMLInputElement).value;
373	  }
374	
375	  protected checked(event: Event): boolean {
376	    return (event.target as HTMLInputElement).checked;
377	  }
378	
379	  protected gradeOf(event: Event): Grade {
380	    return (event.target as HTMLSelectElement).value as Grade;
381	  }
382	
383	  protected claimsOf(personId: number): Claim[] {
384	    return this.claimsByPerson().get(personId) ?? [];
385	  }
386	
387	  protected statementsOf(personId: number): Statement[] {
388	    return this.statementsByPerson().get(personId) ?? [];
389	  }
390	
391	  protected lastStatementOf(personId: number): Statement | null {
392	    return this.statementsOf(personId).at(-1) ?? null;
393	  }
394	
395	  /** Take a statement of the person, and show their claims as it bound or unbound them. */
396	  protected async takeStatement(person: Person): Promise<void> {
397	    this.clearRowError(person.id);
398	    const sheet = this.sheet();
399	    if (!sheet) return;
400	    try {
401	      const taken = await this.statementsService.take(sheet, person.id);
402	      if (this.sheet() !== sheet) return;
403	      for (const c of taken.claims) this.claimSaved(c);
404	      this.statements.update((list) => [...list, taken.statement]);
405	    } catch {
406	      if (this.sheet() !== sheet) return;
407	      this.rowErrors.update((errors) => ({ ...errors, [person.id]: 'A statement could not be taken.' }));
408	    }
409	  }
410	
411	  protected setRetireDate(id: number, date: string): void {
412	    this.retireDates.update((dates) => ({ ...dates, [id]: date }));
413	    this.clearRowError(id);
414	  }
415	
416	  /** Retire the person from the date typed on their row (the sheet's today when blank). */
417	  protected async retire(person: Person): Promise<void> {
418	    this.clearRowError(person.id);
419	    const sheet = this.sheet();
420	    if (!sheet) return;
421	    const from = (this.retireDates()[person.id] ?? '').trim();
422	    if (from !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
423	      this.rowErrors.update((errors) => ({ ...errors, [person.id]: 'Type a date as YYYY-MM-DD.' }));
424	      return;
425	    }
426	    try {
427	      const retired = await this.service.retire(sheet, person.id, from || null);
428	      if (this.sheet() !== sheet) return;
429	      this.put(retired);
430	      this.retireDates.update(({ [person.id]: _, ...rest }) => rest);
431	    } catch {
432	      if (this.sheet() !== sheet) return;
433	      this.rowErrors.update((errors) => ({ ...errors, [person.id]: 'That person could not be retired.' }));
434	    }
435	  }
436	
437	  private clearRowError(id: number): void {
438	    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
439	  }
440	
441	  /** Put the person on hold, or take them off it when held. */
442	  protected async toggleHold(person: Person): Promise<void> {
443	    this.clearRowError(person.id);
444	    const sheet = this.sheet();
445	    if (!sheet) return;
446	    try {
447	      const saved = await this.service.hold(sheet, person.id, !person.held);
448	      if (this.sheet() !== sheet) return;
449	      this.put(saved);
450	    } catch {
451	      if (this.sheet() !== sheet) return;
452	      this.rowErrors.update((errors) => ({
453	        ...errors,
454	        [person.id]: person.held ? 'That person could not be released.' : 'That person could not be held.',
455	      }));
456	    }
457	  }
458	
459	  /** Whether the claim counts in the live totals: OPEN or SETTLED, but not OPEN while its person is
460	   *  on hold. */
461	  private countsLive(claim: Claim, person: Person): boolean {
462	    return counts(claim) && !(person.held && claim.status === 'OPEN');
463	  }
464	
465	  protected claimedOf(person: Person): string {
466	    return money(this.claimedCentsOf(person));
467	  }
468	
469	  /** What the person's OPEN and SETTLED claims add up to (OPEN ones left out while they are on
470	   *  hold); drafts and voided claims do not count. */
471	  private claimedCentsOf(person: Person): number {
472	    return this.claimsOf(person.id).reduce((sum, c) => sum + (this.countsLive(c, person) ? cents(c.amount) : 0), 0);
473	  }
474	
475	  /** The grade's rate in force on the sheet's today. */
476	  private rateOf(grade: Grade): string | null {
477	    const today = this.session.today();
478	    return today === null ? null : rateOn(this.rates(), grade, today);
479	  }
480	
481	  /** The sum of what is due on each of the person's OPEN and SETTLED claims, as each claim shows
482	   *  it (a claim with nothing due is skipped); n/a when no rate of their grade applies on the
483	   *  sheet's today and none of their claims has a figure. */
484	  protected dueTotalOf(person: Person): string | null {
485	    const due = this.dueCentsOf(person);
486	    return due === null ? null : money(due);
487	  }
488	
489	  private dueCentsOf(person: Person): number | null {
490	    let sum = 0;
491	    let any = false;
492	    for (const c of this.claimsOf(person.id)) {
493	      if (!this.countsLive(c, person)) continue;
494	      const due = claimShownCents(c, this.rates(), person.grade, this.floor(), this.lateness());
495	      if (due === null) continue;
496	      sum += due;
497	      any = true;
498	    }
499	    return any || this.rateOf(person.grade) !== null ? sum : null;
500	  }
501	
502	  /** How many of the person's counting claims are overdue, and the sum of what is due on them, in
503	   *  cents, as each claim shows it (a claim with nothing due adds nothing). */
504	  protected overdueOf(person: Person): { count: number; cents: number } {
505	    let count = 0;
506	    let sum = 0;
507	    const today = this.session.today();
508	    for (const c of this.claimsOf(person.id)) {
509	      if (!this.countsLive(c, person) || !overdue(c, this.terms(), today)) continue;
510	      count++;
511	      sum += claimShownCents(c, this.rates(), person.grade, this.floor(), this.lateness()) ?? 0;
512	    }
513	    return { count, cents: sum };
514	  }
515	
516	  protected periodAdded(period: Period): void {
517	    this.periods.update((list) => [...list, period]);
518	  }
519	
520	  protected periodClosed(period: Period): void {
521	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
522	  }
523	
524	  /** Put a set rate in place of the grade's old one for the same from-date. */
525	  protected rateSaved(rate: Rate): void {
526	    this.rates.update((list) => [
527	      ...list.filter((r) => r.grade !== rate.grade || r.from !== rate.from),
528	      rate,
529	    ]);
530	  }
531	
532	  /** Put an added claim first, or a saved one in its place. */
533	  protected claimSaved(claim: Claim): void {
534	    this.claims.update((list) =>
535	      list.some((c) => c.id === claim.id)
536	        ? list.map((c) => (c.id === claim.id ? claim : c))
537	        : [claim, ...list],
538	    );
539	  }
540	
541	  protected edit(person: Person): void {
542	    this.clearRowError(person.id);
543	    this.editingId.set(person.id);
544	    this.editingVersion = person.version;
545	    this.name.set(person.name);
546	    this.grade.set(person.grade);
547	    this.error.set(null);
548	  }
549	
550	  protected reset(): void {
551	    this.editingId.set(null);
552	    this.name.set('');
553	    this.grade.set('A');
554	    this.error.set(null);
555	  }
556	
557	  protected async submit(event: Event): Promise<void> {
558	    event.preventDefault();
559	    if (this.submitting) return;
560	    this.error.set(null);
561	    const sheet = this.sheet();
562	    if (!sheet) return;
563	    const fields = { name: this.name(), grade: this.grade() };
564	    if (!fields.name.trim()) {
565	      this.error.set('Type a name for the person.');
566	      return;
567	    }
568	    const id = this.editingId();
569	    this.submitting = true;
570	    try {
571	      if (id === null) {
572	        const added = await this.service.add(sheet, fields);
573	        if (this.sheet() === sheet) this.people.update((list) => [...list, added]);
574	      } else {
575	        const saved = await this.service.update(sheet, id, this.editingVersion, fields);
576	        if (this.sheet() === sheet) this.put(saved);
577	      }
578	      if (this.sheet() === sheet) this.reset();
579	    } catch (e) {
580	      if (this.sheet() !== sheet) return;
581	      const current = this.staleOf(e);
582	      if (current !== null) {
583	        // Someone else saved the person since the editor loaded them: show them as now stored.
584	        this.put(current);
585	        if (this.editingId() === current.id) {
586	          this.editingVersion = current.version;
587	          this.name.set(current.name);
588	          this.grade.set(current.grade);
589	        }
590	        this.error.set('Someone else saved this person since you opened it; their changes are shown.');
591	        return;
592	      }
593	      if (e instanceof HttpErrorResponse && e.status === 409) {
594	        this.error.set('Another person on the sheet already has that name.');
595	        return;
596	      }
597	      this.error.set(id === null ? 'That person could not be added.' : 'That person could not be saved.');
598	    } finally {
599	      this.submitting = false;
600	    }
601	  }
602	
603	  /** Add a DRAFT claim for the named person, adding them (grade A) first when the name is new. */
604	  protected async quickAdd(event: Event): Promise<void> {
605	    event.preventDefault();
606	    if (this.quickAdding) return;
607	    this.quickError.set(null);
608	    const sheet = this.sheet();
609	    if (!sheet) return;
610	    const name = this.quickName();
611	    if (!name.trim()) {
612	      this.quickError.set('Type a name for the claim.');
613	      return;
614	    }
615	    this.quickAdding = true;
616	    try {
617	      const added = await this.service.quickAdd(sheet, name, this.quickAmount());
618	      if (this.sheet() !== sheet) return;
619	      this.people.update((list) =>
620	        list.some((p) => p.id === added.person.id) ? list : [...list, added.person],
621	      );
622	      this.claimSaved(added.claim);
623	      this.quickName.set('');
624	      this.quickAmount.set('');
625	    } catch (e) {
626	      if (this.sheet() !== sheet) return;
627	      this.quickError.set(
628	        e instanceof HttpErrorResponse && e.status === 423
629	          ? 'That claim falls in a closed period.'
630	          : e instanceof HttpErrorResponse && e.status === 422
631	            ? 'That claim is dated after the person retired.'
632	            : 'That claim could not be added.',
633	      );
634	    } finally {
635	      this.quickAdding = false;
636	    }
637	  }
638	
639	  /** Put a saved person in place of their old row. */
640	  private put(person: Person): void {
641	    this.people.update((list) => list.map((p) => (p.id === person.id ? person : p)));
642	  }
643	
644	  /** The person as now stored, when a save was refused for being made from an older version. */
645	  private staleOf(e: unknown): Person | null {
646	    if (!(e instanceof HttpErrorResponse) || e.status !== 409) return null;
647	    const body = e.error as { error?: unknown; current?: Person } | null;
648	    return body?.error === 'stale' && body.current ? body.current : null;
649	  }
650	
651	  private async read(sheet: string): Promise<void> {
652	    try {
653	      const [list, claims, rates, statements, periods, settings] = await Promise.all([
654	        this.service.list(sheet),
655	        this.claimsService.list(sheet),
656	        this.ratesService.list(sheet),
657	        this.statementsService.list(sheet),
658	        this.periodsService.list(sheet),
659	        this.settingsService.get(sheet),
660	      ]);
661	      if (this.sheet() === sheet) {
662	        this.floor.set(cents(settings.floor));
663	        this.terms.set(settings.terms);
664	        this.latePct.set(settings.latePct);
665	        this.rates.set(rates);
666	        this.periods.set(periods);
667	        this.statements.set(statements);
668	        this.claims.set(claims);
669	        this.people.set(list);
670	      }
671	    } catch {
672	      // The sheet's people could not be read; the list stays empty.
673	    }
674	  }
675	}
